alter table public.catalog_versions add column if not exists artifact_url text null,add column if not exists artifact_sha256 text null,add column if not exists artifact_page_count integer null,add column if not exists renderer_version text null,add column if not exists artifact_generated_at timestamptz null,add column if not exists artifact_registered_by uuid null references public.profiles(id) on delete set null;
alter table public.catalog_versions add constraint catalog_versions_artifact_sha256_format check(artifact_sha256 is null or artifact_sha256 ~ '^[0-9a-f]{64}$'),add constraint catalog_versions_artifact_page_count_positive check(artifact_page_count is null or artifact_page_count>0);
create or replace function public.register_pdf_catalog_artifact_controlled(p_catalog_version_id uuid,p_artifact_url text,p_artifact_sha256 text,p_page_count integer,p_renderer_version text) returns void language plpgsql security definer set search_path='' as $function$
declare v_actor uuid:=auth.uid(); v_status text;
begin if v_actor is null then raise exception using errcode='42501',message='LIHEN_AUTH_REQUIRED'; end if; if not exists(select 1 from public.profiles p where p.id=v_actor and p.authorization_status='ACTIVE' and p.role_code in('OWNER','ADMIN')) then raise exception using errcode='42501',message='LIHEN_CATALOG_WRITE_FORBIDDEN'; end if; select cv.status into v_status from public.catalog_versions cv where cv.id=p_catalog_version_id for update; if v_status is null then raise exception using errcode='P0002',message='LIHEN_CATALOG_VERSION_NOT_FOUND'; end if; if v_status<>'ACTIVE' then raise exception using errcode='55000',message='LIHEN_CATALOG_ARTIFACT_REQUIRES_ACTIVE_VERSION'; end if; if nullif(btrim(p_artifact_url),'') is null then raise exception using errcode='22023',message='LIHEN_CATALOG_ARTIFACT_URL_REQUIRED'; end if; if lower(btrim(p_artifact_sha256)) !~ '^[0-9a-f]{64}$' then raise exception using errcode='22023',message='LIHEN_CATALOG_ARTIFACT_SHA256_INVALID'; end if; if p_page_count is null or p_page_count<=0 then raise exception using errcode='22023',message='LIHEN_CATALOG_ARTIFACT_PAGE_COUNT_INVALID'; end if; if nullif(btrim(p_renderer_version),'') is null then raise exception using errcode='22023',message='LIHEN_CATALOG_RENDERER_VERSION_REQUIRED'; end if; update public.catalog_versions set artifact_url=btrim(p_artifact_url),artifact_sha256=lower(btrim(p_artifact_sha256)),artifact_page_count=p_page_count,renderer_version=btrim(p_renderer_version),artifact_generated_at=now(),artifact_registered_by=v_actor where id=p_catalog_version_id; insert into public.domain_events(id,event_type,aggregate_type,aggregate_id,occurred_at,actor_id,payload,metadata) values(gen_random_uuid(),'CATALOG_PDF_ARTIFACT_REGISTERED','CATALOG_VERSION',p_catalog_version_id,now(),v_actor,jsonb_build_object('sha256',lower(btrim(p_artifact_sha256)),'page_count',p_page_count,'renderer_version',btrim(p_renderer_version)),jsonb_build_object('phase','4')); end; $function$;
revoke all on function public.register_pdf_catalog_artifact_controlled(uuid,text,text,integer,text) from public,anon; grant execute on function public.register_pdf_catalog_artifact_controlled(uuid,text,text,integer,text) to authenticated;
create or replace view public.catalog_pdf_publication_status with(security_invoker=true) as select cv.id catalog_version_id,cv.code,cv.version_label,cv.status,cv.activated_at,cv.artifact_url,cv.artifact_sha256,cv.artifact_page_count,cv.renderer_version,cv.artifact_generated_at,case when cv.status='DRAFT' then 'DRAFT' when cv.status='ACTIVE' and cv.artifact_sha256 is null then 'READY_TO_RENDER' when cv.status='ACTIVE' and cv.artifact_sha256 is not null then 'PUBLISHED' when cv.status='ARCHIVED' then 'ARCHIVED' else 'UNKNOWN' end publication_status from public.catalog_versions cv;
revoke all on public.catalog_pdf_publication_status from public,anon; grant select on public.catalog_pdf_publication_status to authenticated;
